/** 급여테이블 */
export function salaryHtml(st) {
  const d = st.sal; const won = (n) => Math.round(Number(n) || 0).toLocaleString('ko-KR');
  const num = (k, label, step) => '<div class="jh-field"><label class="jh-field__label">' + esc(label) + '</label><input class="jh-input" type="number"' + (step ? ' step="' + step + '"' : '') + ' data-s-field="' + k + '" value="' + esc(d[k] == null ? '' : d[k]) + '"></div>';
  const settings = '<div class="jh-hr__pad"><div class="jh-hr__grid">' + num('minWage', '법정 최저시급(원)') + num('standardRate', '호봉별 표준 인상률(%)', '0.1') + num('perfRateMin', '고과 반영 최소(%)', '0.1') + num('perfRateMax', '고과 반영 최대(%)', '0.1') + num('techAllowancePerCert', '기술수당(자격증 1개당, 원)') + '</div>'
    + '<div class="jh-hr__bar"><button type="button" class="jh-btn" data-variant="primary" data-s-act="save">저장</button><button type="button" class="jh-btn" data-variant="secondary" data-s-act="regen">표 다시 생성</button></div>'
    + '<div class="jh-field__hint"><strong>시급이 기준값</strong>이며 연봉은 시급×209시간×12개월로 계산되어 칸 아래에 작게 표시됩니다. 사원 1호봉은 법정 최저시급에 고정됩니다. 학력에 따른 차등은 두지 않습니다.</div>'
    + '<div class="jh-field__hint">기준값(최저시급·인상률)을 바꿔도 이미 채워진 칸은 그대로이니, 모든 칸을 새 기준으로 맞추려면 "표 다시 생성"(직접 고친 값 포함 전체를 표준공식으로)을 누르세요. 직급 체류연한은 표 위쪽 직급 이름 옆 숫자(년)로 고칩니다.</div>'
    + '<div class="jh-field__hint">기술수당은 근로자 명부에 등록된 자격증 <strong>1개당 ' + won(d.techAllowancePerCert) + '원</strong>씩 상한 없이 누적 지급됩니다(예: 3개 보유 시 ' + won((Number(d.techAllowancePerCert) || 0) * 3) + '원). 개인별 인상률은 고과에 따라 <strong>' + esc(d.perfRateMin) + '%~' + esc(d.perfRateMax) + '%</strong> 사이에서 적용될 수 있으며, 표준(' + esc(d.standardRate) + '%)은 이 표의 기본 인상률입니다.</div>'
    + '<div class="jh-field__hint">⚠️ 참고·내규용 표입니다. 여기서 값을 바꿔도 급여명세서 자동계산에는 반영되지 않습니다(최저시급·기술수당 단가만 다른 화면이 읽어 갑니다).</div></div>';
  const m = salMatrix(d);
  const head = '<tr><th>호봉</th>' + m.cols.map((c) => '<th>' + esc(c.pos) + '<div class="jh-hr__tenure"><input class="jh-input" type="number" min="1" max="30" data-s-tenure="' + esc(c.pos) + '" value="' + c.years + '" aria-label="' + esc(c.pos) + ' 체류연한(년)"> 년</div></th>').join('') + '</tr>';
  const rows = m.rows.map((r) => '<tr><td><strong>' + r.step + '호봉</strong></td>' + r.cells.map((c) => '<td>' + (!c.exists ? '<span class="jh-field__hint">—</span>' : (c.pinned ? '<strong>' + won(c.hourly) + '원</strong>' : '<input class="jh-input" type="number" data-s-cell="' + esc(c.tid) + '|' + esc(c.key) + '" value="' + c.hourly + '" style="max-width:6.5rem;text-align:right" aria-label="' + esc(c.key) + ' 시급"' + (c.below ? ' aria-invalid="true" title="법정 최저시급보다 낮습니다"' : '') + '>') + '<div class="jh-field__hint">연 ' + won(c.annual) + (c.below ? ' <span style="color:var(--c-danger)">최저임금 미달</span>' : '') + '</div>') + '</td>').join('') + '</tr>').join('');
  const table = '<div class="jh-hr__pad"><div class="jh-field__hint">시급(원) · 칸 아래는 연봉 환산</div></div><div class="jh-hr__scroll"><table class="jh-hr-table"><thead>' + head + '</thead><tbody>' + rows + '</tbody></table></div>';
  return '<div class="jh-hr__split">' + card('기준 설정', settings) + card('직급·호봉별 표준 급여테이블 (회사 내규)', table) + '</div>';
}

/** 연봉 제안서 */
const ow = (n) => '₩' + Math.round(n).toLocaleString('ko-KR'); const owh = (n) => '₩' + Number(n).toLocaleString('ko-KR', { maximumFractionDigits: 2 });
const oMoney = (n) => (n || n === 0) && Number(n) ? Number(n).toLocaleString('ko-KR') : '';
export function offerStateText(f) { return f._id ? (f._saved ? '✅ 저장됨' : '✏️ 수정됨 · 아직 저장 안 됨') : '· 저장 안 됨'; }
export function offerResultHtml(st) {
  const f = st.of; const r = offerCalc(f); const lines = []; let body;
  if (r.err) body = '<div class="jh-alert" data-tone="danger" role="alert">⚠️ ' + esc(r.err) + '</div>';
  else if (!r.ok) body = '<div class="jh-empty">연봉 또는 시급을 입력하면<br>급여 구성이 여기에 자동 계산됩니다.</div>';
  else {
    const y = (n) => '연 ' + ow(n * 12); const row2 = (l, m, yr, strong) => '<div class="jh-hr__line"' + (strong ? ' style="font-weight:700"' : '') + '><span class="jh-hr__label">' + l + '</span><span class="jh-hr__val">' + m + (yr ? ' <span class="jh-field__hint">' + yr + '</span>' : '') + '</span></div>';
    lines.push(row2(f.mode === 'annual' ? '환산 통상시급' : '입력 통상시급', owh(r.hourly)), row2('기본근로수당', ow(r.basic), y(r.basic)), row2('주휴수당', ow(r.weekly), y(r.weekly)));
    if (r.etc) lines.push(row2(esc(f.etcName || '기타 고정수당'), ow(r.etc), y(r.etc))); if (r.fixedOT) lines.push(row2('고정연장수당', ow(r.fixedOT), y(r.fixedOT))); if (r.fixedNight) lines.push(row2('고정야간수당', ow(r.fixedNight), y(r.fixedNight)));
    lines.push(row2('월 지급계', ow(r.monthly), '', true), row2('연봉 총액 (세전)', ow(r.annual), '', true));
    const notes = offerNotes(f, r, { minWage: st.minWage, perCert: st.perCert, worker: st.workers.find((x) => x.id === f.workerId) });
    body = lines.join('') + '<div class="jh-field__hint" style="margin-top:var(--sp-3)">' + notes.map((n) => '· ' + esc(n)).join('<br>') + '</div>';
  }
  return card('🧮 자동 계산 결과', '<div class="jh-hr__pad">' + body + '</div>');
}
