  const c3 = card('③ 연봉 · 시급 입력', '<div class="jh-hr__pad"><div>' + rad('mode', 'annual', '연봉으로 입력') + rad('mode', 'hourly', '시급으로 입력') + '</div>' + mny('amount', f.mode === 'annual' ? '연봉 총액 (세전, 원)' : '통상시급 (원)', f.mode === 'annual' ? '예) 36,000,000' : '예) 11,000') + '<div>' + rad('wageType', 'noncomprehensive', '비포괄임금제') + rad('wageType', 'comprehensive', '포괄임금제') + '</div>' + (isWc ? two(mny('fixedOT', '고정연장수당 (월, 원)'), mny('fixedNight', '고정야간수당 (월, 원)')) : '') + two(txt('etcName', '기타 고정수당명 (선택)', '예) 직책수당'), mny('etc', '기타 고정수당 (월, 원)')) + '</div>');
  const c4 = showCur ? card('④ 현재 조건 (재계약 · 조정 비교용)', '<div class="jh-hr__pad">' + two(mny('curSalary', '현재 연봉 (원)'), txt('curRank', '현재 직위 / 직급')) + '<div class="jh-field__hint">' + esc(st.hint || '근로자를 선택하면 최근 연봉계약서의 연봉이 자동으로 채워집니다.') + '</div></div>') : '';
  const c5 = card(showCur ? '⑤ 기타 조건' : '④ 기타 조건', '<div class="jh-hr__pad">' + two(txt('payDay', '급여 지급 시기'), txt('bonus', '상여 · 성과급 (없으면 비움)')) + two(dt('offerDate', '제안일'), dt('replyDue', '회신 기한')) + '<div class="jh-field"><label class="jh-field__label">특약 사항</label><textarea class="jh-textarea" rows="3" data-o-f="special">' + esc(f.special) + '</textarea></div><label class="jh-field__hint"><input type="checkbox" data-o-ck="sepNote"' + (f.sepNote ? ' checked' : '') + '> 연봉 외 별도지급 안내 포함 (기술수당 · 여비교통비)</label></div>');
