  const c2 = card('② 통지일 · 해고일', '<div class="jh-hr__pad"><div class="jh-hr__grid"><div class="jh-field"><label class="jh-field__label">통지일 (이 서면을 교부하는 날)</label><input class="jh-input" type="date" data-d-f="noticeDate" value="' + esc(f.noticeDate) + '"></div><div class="jh-field"><label class="jh-field__label">해고일 (해고 시기)</label><input class="jh-input" type="date" data-d-f="dismissalDate" value="' + esc(f.dismissalDate) + '"></div></div><div id="d-calc">' + dsCalcHtml(st) + '</div>'
    + '<div class="jh-field"><label class="jh-field__label">예고 예외 사유 (해당하는 경우만 · 제26조 단서)</label><label class="jh-field__hint" style="display:flex;gap:var(--sp-2);margin-bottom:var(--sp-2)"><input type="radio" name="d-ex" data-d-ex=""' + (!f.exemptType ? ' checked' : '') + '> 해당 없음 (30일 전 예고 또는 예고수당 지급)</label>' + rad('d-ex', DS_EXEMPT, f.exemptType, 'data-d-ex') + '<div class="jh-field__hint">※ 예외에 해당하는지는 사실관계에 따라 달라집니다. 확실하지 않으면 예외로 선택하지 말고 노무사에게 확인하세요.</div></div>'
    + '<div class="jh-field"><label class="jh-field__label">통상시급 (원) — 해고예고수당 산정용, 최근 연봉·근로계약서 시급을 자동 조회</label><input class="jh-input" inputmode="numeric" data-d-hourly value="' + esc(f.hourly) + '" placeholder="예) 12000"></div></div>');
  const c3 = card('③ 해고 사유', '<div class="jh-hr__pad"><div class="jh-field"><label class="jh-field__label">사유 구분</label>' + rad('d-rs', DS_REASON, f.reasonType, 'data-d-rs') + '</div><div class="jh-field"><label class="jh-field__label">구체적 사유 (필수) — 누가·언제·무엇을 했는지 구체적 사실을 적습니다</label><textarea class="jh-textarea" rows="6" data-d-f="reasonDetail" placeholder="예) 2026. 9. 3.부터 9. 12.까지 회사의 허가 없이 무단결근(6일)하였고, 2026. 9. 8. 이에 대한 서면 경고를 받았음에도 …">' + esc(f.reasonDetail) + '</textarea><div class="jh-field__hint">※ 대법원은 해고사유를 근로자가 알 수 있을 만큼 구체적으로 적어야 한다고 봅니다. 위반한 <b>조문만 나열하는 것은 부족</b>합니다.</div></div><div class="jh-field"><label class="jh-field__label">근거 규정 (선택)</label><input class="jh-input" data-d-f="ruleRef" value="' + esc(f.ruleRef) + '" placeholder="예) 취업규칙 제○조 제○항 제○호"></div></div>');
